let featureConfig={email_otp_ready:false,sms_otp_ready:false,ai_ready:false,whatsapp:''},authChallenge='',authPurpose='register',adminPage='admin-orders',lastSupportId=null;
async function featureAPI(path,data){let r=await fetch('/api/'+path,{method:'POST',headers:{'Content-Type':'application/json',...(token?{Authorization:'Bearer '+token}:{})},body:JSON.stringify(data)}),v=await r.json();if(!r.ok)throw Error(v.error||'تعذر إتمام الطلب');return v}
async function loadFeatureConfig(){try{let r=await fetch('/api/auth-config');if(r.ok)featureConfig=await r.json()}catch{}paintSupport()}
function loginView(){let html=loginViewLegacy();html=html.replace('<label>رقم الهاتف</label><input id="reg-phone" inputmode="tel">','<label>رقم الهاتف</label><input id="reg-phone" inputmode="tel" autocomplete="tel" oninput="scheduleRegistrationOTP()"><button type="button" onclick="requestOTP(\'register\')">إرسال رمز التأكيد للموبايل</button><label>رمز التأكيد (6 أرقام)</label><input id="reg-code" inputmode="numeric" maxlength="6" autocomplete="one-time-code"><p id="otp-status" role="status"></p>');html=html.replace('<button onclick="register()">','<label>أعد كتابة كلمة المرور</label><input id="reg-confirm" type="password" autocomplete="new-password"><button onclick="register()">');html=html.replace(/onclick="alert\('لو نسيت كلمة المرور[^\"]*"/,'onclick="forgotPassword()"');html=html.replace('<button onclick="login()">دخول</button>','<button onclick="login()">دخول</button><button class="secondary" onclick="forgotPassword()">نسيت كلمة المرور؟</button>');html=html.replace('<button onclick="login()">دخول لوحة التحكم</button>','<button onclick="login()">دخول لوحة التحكم</button><button class="secondary" onclick="forgotPassword()">نسيت كلمة المرور؟</button>');return html}
let registrationOtpTimer=0,lastRegistrationOtpNumber='';
function scheduleRegistrationOTP(){clearTimeout(registrationOtpTimer);authChallenge='';let input=$('reg-phone'),value=input.value,phone=value.trim();phone=phone.replace(/[٠-٩]/g,c=>String('٠١٢٣٤٥٦٧٨٩'.indexOf(c))).replace(/[\s()-]/g,'');if(!/^01[0125][0-9]{8}$/.test(phone))return;registrationOtpTimer=setTimeout(()=>{if($('reg-phone')?.value===value&&lastRegistrationOtpNumber!==phone)requestOTP('register')},700)}
async function requestOTP(purpose){const method=purpose==='register'?'phone':purpose==='link'?'email':$('reset-method').value,id=purpose==='register'?'reg-phone':purpose==='link'?'link-email':'reset-destination',destination=$(id).value.trim();let status=$('otp-status');authChallenge='';status.textContent='جارٍ إرسال الرمز…';try{let v=await featureAPI('auth/send-code',{[method]:destination,purpose});if($(id)?.value.trim()!==destination)return;authChallenge=v.challenge_id;authPurpose=purpose;if(purpose==='register')lastRegistrationOtpNumber=destination.replace(/[٠-٩]/g,c=>String('٠١٢٣٤٥٦٧٨٩'.indexOf(c))).replace(/[\s()-]/g,'');status.textContent=v.message}catch(e){status.textContent=e.message}}
async function register(){try{if(authPurpose!=='register'||!authChallenge)throw Error('اطلب رمز التأكيد للموبايل أولًا');await featureAPI('register',{name:$('reg-name').value,phone:$('reg-phone').value,password:$('reg-pass').value,confirm_password:$('reg-confirm').value,challenge_id:authChallenge,code:$('reg-code').value.trim()});authChallenge='';alert('تم تأكيد رقم الموبايل وإنشاء حسابك. سجل الدخول الآن.');render()}catch(e){alert(e.message)}}
function forgotPassword(){authChallenge='';authPurpose='reset';$('app').innerHTML=`<section class="card" style="max-width:480px;margin:auto"><h2>استرجاع كلمة المرور</h2><p>اختار الموبايل أو البريد المرتبط بحسابك لاستقبال الرمز.</p><label>طريقة استلام الرمز</label><select id="reset-method" onchange="authChallenge='';$('reset-destination').value='';$('reset-destination').type=this.value==='email'?'email':'tel';$('reset-destination').placeholder=this.value==='email'?'بريدك المؤكد':'رقم الموبايل المسجل';$('otp-status').textContent=''"><option value="phone">رسالة SMS على الموبايل</option><option value="email">رسالة على الإيميل</option></select><label>رقم الموبايل أو البريد حسب اختيارك</label><input id="reset-destination" type="tel" autocomplete="username" placeholder="رقم الموبايل المسجل"><button onclick="requestOTP('reset')">إرسال رمز الاسترجاع</button><p id="otp-status" role="status"></p><label>رمز التأكيد (6 أرقام)</label><input id="reset-code" maxlength="6" inputmode="numeric" autocomplete="one-time-code"><label>كلمة المرور الجديدة (10 أحرف على الأقل)</label><input id="reset-pass" type="password" autocomplete="new-password"><label>أعد كتابة كلمة المرور</label><input id="reset-confirm" type="password" autocomplete="new-password"><button onclick="resetForgottenPassword()">حفظ كلمة المرور</button><button class="secondary" onclick="render()">رجوع لتسجيل الدخول</button></section>`;paintSupport()}
async function resetForgottenPassword(){try{await featureAPI('auth/reset-password',{challenge_id:authChallenge,code:$('reset-code').value.trim(),password:$('reset-pass').value,confirm_password:$('reset-confirm').value});authChallenge='';alert('اتغيرت كلمة المرور. سجل الدخول بكلمة المرور الجديدة.');render()}catch(e){alert(e.message)}}
let selectedDriverId=null,driverTripDate='';
function cairoTripDate(value){if(!value)return '';let date=new Date(value);if(Number.isNaN(date.getTime()))return String(value).slice(0,10);let parts=new Intl.DateTimeFormat('en-GB',{timeZone:'Africa/Cairo',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(date);let part=k=>parts.find(x=>x.type===k)?.value||'';return `${part('year')}-${part('month')}-${part('day')}`}
function openDriverTrips(id){selectedDriverId=id;driverTripDate='';render();document.querySelector('#driver-trip-search')?.scrollIntoView({behavior:'smooth',block:'start'})}
function showAllDriverTrips(){selectedDriverId=null;driverTripDate='';render()}
function clearDriverTripDate(){driverTripDate='';render()}
function closeDriverDialog(id){document.getElementById(id)?.remove()}
function openDriverTrip(id){const order=state.orders.find(o=>o.id===id&&o.driver_id===selectedDriverId);if(!order)return;closeDriverDialog('driver-trip-dialog');let dialog=document.createElement('dialog');dialog.id='driver-trip-dialog';dialog.className='admin-trip-dialog';dialog.innerHTML=`<div class="admin-trip-dialog-head"><strong>تفاصيل الطلب #${order.id} · ${esc(order.customer)}</strong><button class="secondary" onclick="closeDriverDialog('driver-trip-dialog')">إغلاق ✕</button></div><div class="admin-trip-dialog-body"><button class="driver-chat-open" onclick="openDriverChat(${order.id})">💬 عرض رسائل العميل والطيار · ${Number(state.chat_counts?.[String(order.id)]||0)} رسالة</button>${tripDetails(order,'admin')}</div>`;document.body.append(dialog);dialog.addEventListener('close',()=>dialog.remove());dialog.showModal()}
let driverChatRequest=0;
async function loadDriverChat(id,after=0){let dialog=document.getElementById('driver-chat-dialog'),stream=dialog?.querySelector('#driver-chat-stream'),statusEl=dialog?.querySelector('#driver-chat-status'),more=dialog?.querySelector('#driver-chat-more'),request=++driverChatRequest;if(!dialog||!stream)return;statusEl.textContent='جارٍ تحميل الرسائل…';more.hidden=true;try{const result=await featureAPI('admin/chat/archive',{order_id:id,after_id:after});if(request!==driverChatRequest||!dialog.isConnected)return;const messages=result.messages||[];if(!after)stream.innerHTML='';stream.insertAdjacentHTML('beforeend',messages.map(m=>`<article class="admin-message ${m.sender_role==='driver'?'from-driver':'from-customer'}"><span class="chat-author">${m.sender_role==='driver'?'🛵 الطيار':'👤 العميل'} · ${esc(m.sender_name)}</span><p>${esc(m.body)}</p><time datetime="${esc(m.at)}">${esc(new Date(m.at).toLocaleString('ar-EG',{timeZone:'Africa/Cairo',dateStyle:'short',timeStyle:'short'}))}</time></article>`).join(''));if(!stream.children.length)stream.innerHTML='<p class="muted">لا توجد رسائل محفوظة لهذا المشوار حتى الآن.</p>';statusEl.textContent=`${stream.querySelectorAll('.admin-message').length} رسالة معروضة`;more.hidden=!result.has_more;more.onclick=()=>loadDriverChat(id,result.next_id)}catch(e){if(request===driverChatRequest&&dialog.isConnected)statusEl.textContent='تعذر تحميل المحادثة: '+e.message}}
function openDriverChat(id){const order=state.orders.find(o=>o.id===id);if(!order)return;closeDriverDialog('driver-chat-dialog');let dialog=document.createElement('dialog');dialog.id='driver-chat-dialog';dialog.className='admin-trip-dialog admin-chat-dialog';dialog.innerHTML=`<div class="admin-trip-dialog-head"><strong>💬 رسائل الطلب #${order.id}</strong><button class="secondary" onclick="closeDriverDialog('driver-chat-dialog')">إغلاق ✕</button></div><div class="admin-trip-dialog-body"><p>بين ${esc(order.customer)} والطيار ${esc(order.driver_name||'السابق')}</p><div class="chat-participants"><span>👤 ${esc(order.customer)}</span><span>🛵 ${esc(order.driver_name||'الطيار')}</span></div><div id="driver-chat-stream" class="admin-chat-stream" role="log" aria-label="محادثة العميل والطيار"></div><p id="driver-chat-status" role="status"></p><button id="driver-chat-more" hidden>عرض رسائل إضافية</button><button class="secondary" onclick="loadDriverChat(${id})">تحديث الرسائل</button></div>`;document.body.append(dialog);dialog.addEventListener('close',()=>dialog.remove());dialog.showModal();loadDriverChat(id)}
function driverDirectory(){let driver=state.drivers.find(d=>d.id===selectedDriverId),orders=driver?state.orders.filter(o=>o.driver_id===driver.id):[],visible=driverTripDate?orders.filter(o=>cairoTripDate(o.created_at)===driverTripDate):orders;return driver?`<section class="card" id="driver-trip-search"><div class="section-heading"><h2>مشاوير ${esc(driver.name)}</h2><button class="secondary" onclick="showAllDriverTrips()">→ كل الطيارين</button></div><div class="driver-trip-filter"><label>تاريخ المشوار · بتوقيت مصر<input type="date" value="${esc(driverTripDate)}" onchange="driverTripDate=this.value;render()"></label><button class="secondary" onclick="clearDriverTripDate()">كل الأيام</button></div><p>${visible.length} طلب${driverTripDate?' يوم '+esc(driverTripDate):''}</p><div class="driver-order-cards">${visible.map(o=>`<article class="driver-order-card"><button class="driver-order-main" onclick="openDriverTrip(${o.id})"><span class="driver-order-top"><strong>طلب #${o.id}</strong><span class="tag">${esc(status[o.status]||o.status)}</span></span><span class="driver-order-title">${esc(o.customer)} · ${esc(o.kind==='ride'?'مشوار':o.kind==='products'?'طلب منتجات':'توصيل')}</span><span class="driver-order-meta">${esc(cairoTripDate(o.created_at))} · ${esc(o.area||'')} · ${money(o.total)}</span><span class="driver-order-link">عرض تفاصيل الطلب ←</span></button><button class="driver-order-chat" onclick="openDriverChat(${o.id})">💬 الرسائل (${Number(state.chat_counts?.[String(o.id)]||0)})</button></article>`).join('')||'<p class="muted">لا توجد طلبات للطيار في اليوم المحدد.</p>'}</div></section>`:`<section class="card"><h2>قائمة التعيين · الطيارون</h2><p>اختار طيارًا لعرض طلباته حسب التاريخ.</p><div class="driver-tiles">${state.drivers.map(d=>`<div class="driver-tile"><button class="driver-tile-open" onclick="openDriverTrips(${d.id})"><span class="driver-directory-avatar"><span class="driver-directory-initial" aria-hidden="true">${esc((d.name||"ط").trim().charAt(0)||"ط")}</span>${d.photo?`<img src="${esc(d.photo)}" alt="صورة ${esc(d.name)}" loading="lazy" decoding="async" onerror="this.remove()">`:""}</span><strong>${esc(d.name)}</strong><span>${esc(d.area)} · ${state.orders.filter(o=>o.driver_id===d.id).length} طلب · ${d.disabled?'حساب موقوف':d.available?'متاح':'غير متاح'}</span></button><details><summary>إدارة الطيار</summary><p>${esc(d.username||d.phone)} · ${esc(d.email||'بدون إيميل')}</p><div class="row">${d.disabled?`<button onclick="restoreDriver(${d.id})">استرجاع الطيار</button>`:`<button onclick="editDriver(${d.id})">تعديل الطيار</button><button class="secondary" onclick="deleteDriver(${d.id})">حذف الطيار</button><button onclick="driverAvailable(${d.id},${!d.available})">${d.available?'إيقاف التوافر':'تشغيل التوافر'}</button><button onclick="resetDriverPassword(${d.id})">إعادة تعيين كلمة المرور</button>`}</div></details></div>`).join('')||'<p>لم تضف طيارين بعد.</p>'}</div></section>`}
function editDriver(id){let d=state.drivers.find(x=>x.id===id);if(!d)return;let root=$('driver-editor');if(!root){root=document.createElement('div');root.id='driver-editor';$('admin-workspace').prepend(root)}root.innerHTML=`<section class="card"><h3>تعديل الطيار</h3><label>الاسم بالعربي أو الإنجليزي</label><input id="edit-driver-name" value="${esc(d.name)}"><label>اسم المستخدم</label><input id="edit-driver-username" value="${esc(d.username)}"><label>رقم الهاتف</label><input id="edit-driver-phone" value="${esc(d.phone)}"><label>إيميل الطيار</label><input id="edit-driver-email" type="email" value="${esc(d.email||'')}"><label>المنطقة</label><select id="edit-driver-area">${options(state.areas,d.area)}</select><button onclick="saveDriverEdit(${id})">حفظ التعديل</button><button class="secondary" onclick="$('driver-editor').remove()">إلغاء</button></section>`;root.scrollIntoView({block:'start'})}
async function saveDriverEdit(id){try{await api('driver/update',{id,name:$('edit-driver-name').value,username:$('edit-driver-username').value,phone:$('edit-driver-phone').value,email:$('edit-driver-email').value,area:$('edit-driver-area').value})}catch(e){alert(e.message)}}
async function deleteDriver(id){if(!confirm('حذف حساب الطيار من التشغيل؟ سيبقى سجل الطلبات والمحفظة ويمكن استرجاع الحساب.'))return;try{await api('driver/delete',{id})}catch(e){alert(e.message)}}
async function restoreDriver(id){try{await api('driver/restore',{id})}catch(e){alert(e.message)}}
function ratingPanel(o){if(!state||!['customer','driver'].includes(tab)||o.status!=='delivered'||!o.driver_id)return '';let mine=(state.ratings||[]).find(r=>r.order_id===o.id&&r.sender_id===state.user.id);return `<section class="card"><h3>تقييم ${tab==='customer'?'الطيار':'العميل'}</h3><p>اختار عدد النجوم:</p><div class="star-choices" role="radiogroup" aria-label="تقييم من خمس نجوم">${[1,2,3,4,5].map(stars=>`<label class="star-choice"><input type="radio" name="stars-${o.id}" value="${stars}" ${stars===(mine?.stars||5)?'checked':''}><span aria-hidden="true">${'★'.repeat(stars)}${'☆'.repeat(5-stars)}</span><span class="sr-only">${stars} من ٥ نجوم</span></label>`).join('')}</div><label>تعليق اختياري<textarea id="rating-comment-${o.id}" maxlength="500">${esc(mine?.comment||'')}</textarea></label><button onclick="saveRating(${o.id})">${mine?'تحديث التقييم':'إرسال التقييم'}</button>${tab==='customer'?complaintPanel(o):''}</section>`}
function complaintPanel(o){return `<details><summary>عندك شكوى من الطيار؟</summary><p>الشكوى تروح للإدارة للمراجعة، وهي منفصلة عن النجوم.</p><label>نوع الشكوى<select id="complaint-category-${o.id}"><option>تأخير</option><option>أسلوب التعامل</option><option>مشكلة في الطلب</option><option>مشكلة في القيادة</option><option>أخرى</option></select></label><label>تفاصيل اختيارية<textarea id="complaint-details-${o.id}" maxlength="1000"></textarea></label><button onclick="sendDriverComplaint(${o.id})">إرسال الشكوى</button></details>`}
async function sendDriverComplaint(id){if(!await window.appConfirm('إرسال الشكوى للإدارة للمراجعة؟',{title:'إرسال الشكوى',confirmText:'إرسال الشكوى'}))return;try{await featureAPI('driver/complaint',{order_id:id,category:$('complaint-category-'+id).value,details:$('complaint-details-'+id).value});alert('وصلت الشكوى للإدارة')}catch(e){alert(e.message)}}
async function saveRating(id){try{await api('rating',{order_id:id,stars:Number(document.querySelector('input[name="stars-'+id+'"]:checked')?.value),comment:$('rating-comment-'+id).value})}catch(e){alert(e.message)}}
function adminRatings(){let all=state.ratings||[];return `<section class="card"><h2>تقييم العملاء والطيارين</h2>${all.map(r=>`<div class="pill">طلب #${r.order_id} · ${esc(r.sender_name)} قيّم ${esc(r.target_name)}: <strong>${r.stars} / 5</strong><p>${esc(r.comment)}</p></div>`).join('')||'<p>تظهر التقييمات بعد تسليم الطلبات.</p>'}<h3>شكاوى الطيارين</h3>${(state.driver_complaints||[]).map(c=>`<div class="pill">طلب #${c.order_id} · ${esc(c.customer_name)} اشتكى من ${esc(c.driver_name)} · ${esc(c.category)}<p>${esc(c.details)}</p></div>`).join('')||'<p>لا توجد شكاوى.</p>'}</section>`}
function adminSupport(){return `<section class="card"><h2>إشعارات ودعم العملاء والطيارين</h2><p>${state.ai_ready?'بوت الذكاء الاصطناعي متصل':'بوت الذكاء الاصطناعي يحتاج ربط خدمة الذكاء الاصطناعي'} · ${state.sms_otp_ready?'إرسال OTP للموبايل متصل':'إرسال OTP للموبايل يحتاج ربط خدمة SMS'}</p>${(state.support_tickets||[]).map(t=>`<div class="card"><strong>#${t.id} · ${esc(t.name)} · ${t.status==='open'?'تحتاج مراجعة':'تم الرد'}</strong><p>${esc(t.message)}</p>${t.answer?`<p>${t.ai?'رد البوت':'رد الدعم'}: ${esc(t.answer)}</p>`:''}<label>رد المسؤول</label><textarea id="support-reply-${t.id}" maxlength="2000"></textarea><button onclick="replySupport(${t.id})">إرسال الرد</button></div>`).join('')||'<p>لا توجد رسائل دعم.</p>'}</section>`}
async function replySupport(id){try{await api('support/reply',{id,answer:$('support-reply-'+id).value})}catch(e){alert(e.message)}}
function adminSectionHTML(id){switch(id){case 'admin-drivers':return `<div class="card" id="admin-drivers"><h3>أضف طيارًا</h3><label>الاسم</label><input id="d-name"><label>الهاتف</label><input id="d-phone"><label>إيميل الطيار (اختياري)</label><input id="d-email" type="email" autocomplete="off"><label>اسم المستخدم (حروف عربية أو إنجليزية)</label><input id="d-username" autocomplete="off"><label>كلمة مرور المندوب (10 أحرف على الأقل)</label><input id="d-password" type="password" autocomplete="new-password"><label>أعد كتابة كلمة المرور</label><input id="d-confirm" type="password" autocomplete="new-password"><label>المركبة</label><select id="d-vehicle"><option>موتوسيكل</option><option>سكوتر</option><option>عجلة</option><option>توك توك</option><option>سيارة</option><option>ميكروباص</option></select><label>المنطقة</label><select id="d-area">${options(state.areas)}</select><button onclick="addDriver()">حفظ المندوب</button></div>`;case 'admin-merchants':return `<div class="card" id="admin-merchants"><h3>أماكن المحلات والصيدليات</h3><p class="muted">لو البضاعة كلها عندك، ثبت مكان استلامها مرة واحدة هنا. بعدها السعر والكمية وزر «نشر للعميل» يكفوا لكل منتج.</p><input id="m-name" placeholder="اسم المحل"><select id="m-category">${options(state.categories.filter(c=>c.active).map(c=>c.name))}</select><select id="m-area">${options(state.areas)}</select><input id="m-address" placeholder="عنوان المحل بالتفصيل"><div id="merchant-map" class="map"></div><p id="merchant-point" class="map-legend">اضغط الخريطة لتحديد مكان استلام المنتجات الحقيقي</p><button onclick="setupWarehouse()">تثبيت مخزن ولعه وربط المنتجات</button><p class="muted">${state.settings.warehouse_address?'مكان الاستلام: '+esc(state.settings.warehouse_address):'حدده مرة واحدة قبل نشر أول منتج'}</p><button onclick="createMerchant()">حفظ محل منفصل (اختياري)</button>${state.merchants.map(m=>`<div class="pill">${esc(m.name)} · ${esc(m.category)} · ${esc(m.area)} · ${esc(m.address)} <button onclick="toggleMerchant(${m.id},${m.active?'false':'true'})">${m.active?'إيقاف':'تشغيل'}</button></div>`).join('')}</div>`;case 'admin-categories':return adminCatalogCards('categories');case 'admin-settings':return `<div class="card" id="admin-settings"><h3>إعدادات الدفع والتوصيل</h3><label>رقم المحفظة</label><input id="s-wallet" value="${esc(state.settings.wallet)}"><label>رقم / حساب إنستاباي</label><input id="s-instapay" value="${esc(state.settings.instapay||'')}"><label>واتساب الشكاوى والمقترحات</label><input id="s-whatsapp" value="${esc(state.settings.whatsapp)}"><button onclick="saveSettings()">حفظ الأرقام</button></div>`;case 'admin-delivery-rate':return `<div class="card" id="admin-delivery-rate"><h3>سعر الكيلومتر للتوصيل</h3><label for="s-km-rate">جنيه لكل كيلومتر</label><input id="s-km-rate" type="number" min="0.01" max="10000" step="0.01" value="${esc(state.settings.per_km_rate||'')}" placeholder="حدد سعرك"><p class="muted">للمنتجات وتوصيل الشحنات: مسافة الطريق من الاستلام إلى التسليم × سعر الكيلومتر. السعر يثبت عند تأكيد الطلب. اتركه فارغًا للعودة للتسعير السابق؛ المشاوير والخدمات الأخرى تظل بتسعير الإدارة.</p><button onclick="saveKmRate()">حفظ سعر الكيلومتر</button><p>${state.settings.per_km_rate?'مفعّل: '+money(state.settings.per_km_rate)+' / كم':'غير مفعّل؛ حدد السعر لتشغيله'}</p></div>`;case 'admin-ride-rates':return `<div class="card" id="admin-ride-rates"><h3>تسعيرة المشاوير حسب المركبة</h3><p class="muted">سعر أول ٣ كم، ثم زيادة لكل كيلومتر إضافي أو جزء منه. اترك السعرين فارغين لتعود المركبة لمراجعة المسؤول.</p>${rideVehicles.map(v=>`<div class="ride-rate-row"><strong>${v.icon} ${v.label}</strong><label>أول ٣ كم<input id="ride-base-${v.key}" type="number" min="0.01" max="10000" step="0.01" value="${esc(state.settings[v.key+'_base']||'')}" placeholder="جنيه"></label><label>كل كم إضافي<input id="ride-extra-${v.key}" type="number" min="0.01" max="10000" step="0.01" value="${esc(state.settings[v.key+'_extra']||'')}" placeholder="جنيه"></label><button onclick="saveRideRate('${v.key}')">حفظ</button></div>`).join('')}</div>`;case 'admin-map-section':return `<div class="card" id="admin-map-section"><h3>خريطة الطلبات والمندوبين</h3><p class="map-legend">الأزرق موقع المحل، البرتقالي عنوان العميل، والأخضر آخر موقع شاركه المندوب. اضغط على العلامة للتفاصيل.</p><div id="admin-map" class="map"></div></div>`;case 'admin-services':return adminCatalogCards('services');default:return ''}}
function renderAdmin(){const section=id=>adminSectionHTML(id);const nav=[['admin-overview','ملخص الإدارة'],['admin-orders','قائمة الطلبات'],['admin-driver-list','قائمة التعيين'],['admin-driver-shifts','شيفتات الطيارين'],['admin-map-section','الديليفري · خريطة الشاشة'],['admin-daily','حركة الأيام'],['admin-activity','حركة الصرف والسجل'],['admin-products','المنتجات'],['admin-merchants','المحلات'],['admin-categories','الأقسام'],['admin-wallets','المحفظة · قفل بكلمة سر'],['admin-delivery-rate','أسعار التوصيل'],['admin-commission','نسب ولعه'],['admin-services','الخدمات'],['admin-ratings','التقييمات'],['admin-featured','تقييمات العملاء'],['admin-support','إشعارات الدعم'],['admin-payment','أرقام الدفع'],['admin-settings','الإعدادات'],['admin-team','أعضاء الفريق']];const staff=Array.isArray(state.staff_permissions);if(staff&&!state.staff_permissions.includes(adminPage))adminPage=state.staff_permissions[0]||'admin-overview';let content='';if(adminPage==='admin-orders'){content=`<div class="admin-section-intro"><span>مركز التشغيل</span><h2>قائمة الطلبات</h2><p>${state.orders.length} طلب مسجل · تابع الحالة والتعيين والتفاصيل من البطاقات.</p></div>${tripDetails(state.orders.find(o=>o.id===selectedTripId),'admin')}<div class="admin-order-tools"><label>عرض الطلبات<select id="order-filter" onchange="orderFilter=this.value;render()">${options(['الجارية','تحتاج مراجعة','المنتهية','الكل'],orderFilter)}</select></label></div>${state.orders.filter(o=>orderFilter==='الكل'||(orderFilter==='المنتهية'?['delivered','cancelled'].includes(o.status):orderFilter==='تحتاج مراجعة'?['new','medicine_review','payment_review','awaiting_quote'].includes(o.status):!['delivered','cancelled'].includes(o.status))).map(o=>orderCard(o,'admin')).join('')||'<div class="empty">لا توجد طلبات في هذا العرض.</div>'}`}else if(adminPage==='admin-driver-list'){content=driverDirectory()+section('admin-drivers')}else if(adminPage==='admin-driver-shifts')content=adminDriverShifts();else if(adminPage==='admin-overview')content=adminOverview();else if(adminPage==='admin-wallets')content=adminDriverWallets();else if(adminPage==='admin-cash')content=adminDriverWallets();else if(adminPage==='admin-chat-archive')content=adminChatArchive();else if(adminPage==='admin-ratings')content=adminRatings();else if(adminPage==='admin-payment')content=adminPaymentNumbers();else if(adminPage==='admin-team')content=adminTeamPage();else if(adminPage==='admin-featured')content=adminFeatured();else if(adminPage==='admin-support')content=adminSupport();else if(adminPage==='admin-daily')content=adminDailyLedger();else if(adminPage==='admin-activity')content=adminActivityPage();else if(adminPage==='admin-products')content=adminProductStudio();else if(adminPage==='admin-delivery-rate')content=`<div class="admin-section-intro"><span>الأسعار</span><h2>أسعار التوصيل والمشاوير</h2><p>حدد سعر الكيلومتر وتسعيرة كل مركبة، ثم احفظ التعديل.</p></div>`+section('admin-delivery-rate')+section('admin-ride-rates');else if(adminPage==='admin-map-section')content=`<div class="admin-section-intro"><span>المتابعة المباشرة</span><h2>خريطة الطلبات والطيارين</h2><p>تابع مواقع الطلبات وآخر موقع شاركه الطيار.</p></div>`+section('admin-map-section');else if(adminPage==='admin-commission')content=adminCommissionStudio();else content=(['admin-categories','admin-settings'].includes(adminPage)?`<div class="admin-section-intro"><span>${adminPage==='admin-settings'?'ضبط الحساب':'تنظيم الكتالوج'}</span><h2>${adminPage==='admin-settings'?'الإعدادات':'الأقسام'}</h2><p>${adminPage==='admin-settings'?'بيانات الدفع والحساب والدعم في مكان واحد.':'راجع الأقسام وحالة ظهورها للعملاء.'}</p></div>`:'')+section(adminPage)+(adminPage==='admin-settings'?emailRecoveryPanel()+supportSettingsPanel()+googleMapsSettingsPanel():'');const icons={'admin-overview':'▦','admin-orders':'▤','admin-driver-list':'◉','admin-driver-shifts':'◷','admin-map-section':'⌖','admin-daily':'▥','admin-activity':'◴','admin-products':'◈','admin-merchants':'▣','admin-categories':'▦','admin-wallets':'◫','admin-delivery-rate':'↗','admin-commission':'٪','admin-services':'✦','admin-ratings':'★','admin-featured':'♛','admin-support':'✉','admin-payment':'◉','admin-settings':'⚙','admin-team':'♧'};return `<div class="admin-layout"><aside class="admin-sidebar" aria-label="قائمة الإدارة"><div class="admin-sidebar-brand"><span class="admin-sidebar-mark" aria-hidden="true">و</span><div><strong>إدارة ولعه</strong><small>لوحة التحكم</small></div></div><div class="admin-sidebar-label">القائمة الرئيسية</div><div class="admin-sidebar-links">${nav.filter(([id])=>!staff||state.staff_permissions.includes(id)).map(([id,label])=>`<button class="admin-nav-card ${id===adminPage?'on':''}" aria-current="${id===adminPage?'page':'false'}" onclick="openAdminPage('${id}')"><span class="admin-nav-icon" aria-hidden="true">${icons[id]||'•'}</span><span class="admin-nav-text">${label}</span>${id==='admin-support'&&(state.support_tickets||[]).filter(t=>t.status==='open').length?`<b class="admin-nav-count">${(state.support_tickets||[]).filter(t=>t.status==='open').length}</b>`:''}</button>`).join('')}</div><button class="admin-notification-toggle" onclick="enableNotifications()">♬ &nbsp; تفعيل إشعارات الطلبات</button></aside><section id="admin-workspace" class="admin-workspace ${staff?'staff-view':''} ${adminPage==='admin-map-section'?'delivery-map-workspace':''}">${staff?'<p class="staff-notice">صلاحية عرض فقط · الإدارة المالية والتعديل للمسؤول الرئيسي.</p>':''}${content}</section></div>`}
function supportSettingsPanel(){let wa=String(state?.settings?.whatsapp||featureConfig.whatsapp||'').replace(/\D/g,'');if(wa.startsWith('01')&&wa.length===11)wa='2'+wa;return `<section class="support-settings card"><h3>الدعم والتواصل</h3><p>تواصل مع إدارة ولعه أو راجع رسائل الدعم.</p><div class="row"><button onclick="openSupport()">💬 افتح الدعم</button>${wa?`<a class="route-link" target="_blank" rel="noopener" href="https://wa.me/${wa}">واتساب الشكاوى والمقترحات</a>`:''}</div></section>`}
function paintSupport(){$('support-dock')?.remove();let latest=Math.max(0,...(state?.support_tickets||[]).map(t=>t.id));if(state?.user?.role==='admin'&&lastSupportId!==null&&latest>lastSupportId&&window.Notification?.permission==='granted')new Notification('ولعه · رسالة دعم جديدة',{body:'افتح إشعارات الدعم لمراجعة الرسالة'});lastSupportId=state?.user?.role==='admin'?latest:null}
async function openSupport(){if(state&&!previewMode)await refresh();let existing=$('support-dialog');if(existing)existing.remove();let el=document.createElement('dialog');el.id='support-dialog';el.innerHTML=`<h2>دعم ولعه</h2><button aria-label="إغلاق الدعم" onclick="$('support-dialog').close();$('support-dialog').remove()">إغلاق</button>${!state||previewMode?'<p>سجل الدخول لإرسال رسالة للدعم، أو تواصل من أيقونة واتساب.</p>':`<p>${state.ai_ready?'تقدر تسأل البوت أو تبعت للمسؤول.':'ابعت للمسؤول وسيرد عليك هنا.'}</p>${state.ai_ready?'<label><input id="support-ai" type="checkbox" style="width:auto"> استخدام بوت الذكاء الاصطناعي (رسالتك ستُرسل لخدمة OpenAI، لا تكتب بيانات طبية أو كلمات مرور)</label>':''}<label>رسالتك</label><textarea id="support-message" maxlength="1000"></textarea><button id="support-send" onclick="sendSupport()">إرسال للدعم</button><p id="support-result" role="status"></p><h3>رسائلك والردود</h3>${(state.support_tickets||[]).map(t=>`<div class="pill"><p>${esc(t.message)}</p><p>${esc(t.answer||'بانتظار المسؤول')}</p></div>`).join('')}`}`;document.body.append(el);el.showModal()}
async function sendSupport(){let button=$('support-send');button.disabled=true;try{let v=await featureAPI('support',{message:$('support-message').value,use_ai:!!$('support-ai')?.checked});$('support-result').textContent=v.answer;$('support-message').value='';await refresh()}catch(e){$('support-result').textContent=e.message}finally{button.disabled=false}}

function emailRecoveryPanel(){if(state?.user.role==='driver')return `<section class="card"><h3>إيميل الطيار</h3><p>${esc(state.user.email||'لم يحدد المسؤول إيميلًا بعد')}</p><p>الإيميل يحدده ويعدّله المسؤول من الداشبورد فقط.</p></section>`;return `<section class="card"><h3>بريد استرجاع الحساب</h3><p>${state.user.email?'بريدك المؤكد: '+esc(state.user.email):'اربط بريدًا مؤكدًا لتقدر تسترجع كلمة المرور بنفسك.'}</p><label>البريد الإلكتروني</label><input id="link-email" type="email"><button onclick="requestOTP('link')">إرسال رمز التأكيد</button><p id="otp-status" role="status"></p><label>رمز التأكيد</label><input id="link-code" maxlength="6" inputmode="numeric"><label>كلمة المرور الحالية</label><input id="link-password" type="password" autocomplete="current-password"><button onclick="linkRecoveryEmail()">تأكيد وربط البريد</button></section>`}
async function linkRecoveryEmail(){try{await featureAPI('auth/link-email',{challenge_id:authChallenge,code:$('link-code').value.trim(),current_password:$('link-password').value});authChallenge='';await refresh();alert('تم ربط البريد المؤكد بحسابك.')}catch(e){alert(e.message)}}

function cleanupCustomerArchive(){if(!state||tab!=='customer'||previewMode)return;const active=new Set(state.orders.map(chatKey));for(const cache of [chatCache,chatDrafts])for(const key of cache.keys())if(!active.has(key))cache.delete(key);if(trackingOrderId&&!state.orders.some(o=>o.id===trackingOrderId))trackingOrderId=null}
function protectedWalletPage(){if(!state.wallet_unlocked)return `<section class="card wallet-lock-card"><div class="wallet-lock-icon">🔒</div><h2>محافظ الطيارين</h2><p>اكتب كلمة سر لوحة التحكم لعرض الأرصدة والتسويات. تقفل الصفحة تلقائيًا بعد خمس دقائق.</p><label>كلمة سر لوحة التحكم<input id="wallet-unlock-password" type="password" autocomplete="current-password" onkeydown="if(event.key==='Enter')unlockWallets()"></label><button onclick="unlockWallets()">فتح المحافظ ←</button><p id="wallet-unlock-status" role="status"></p></section>`;const wallets=state.drivers.map(d=>({driver:d,w:state.driver_wallets?.[d.id]})).filter(x=>x.w),sum=key=>wallets.reduce((n,x)=>n+Number(x.w[key]||0),0),metric=(label,value,detail)=>`<div class="wallet-metric"><span>${label}</span><strong>${ledgerCurrency(value)}</strong><small>${detail}</small></div>`;return `<section class="wallet-page"><div class="wallet-heading"><div><span>الحسابات والتسويات</span><h2>محافظ الطيارين</h2><p>افتح بطاقة الطيار لمراجعة حركاته أو تسجيل تسوية.</p></div><button class="secondary" onclick="lockWallets()">🔒 قفل المحافظ</button></div><div class="wallet-overview">${metric('صافي مستحقات الطيارين',sum('balance'),'المتبقي في المحافظ')}${metric('حصة ولعه القائمة',sum('commission_due'),'لم تسجل تسويتها')}${metric('الكاش غير المسوّى',sum('cash_due'),'محصل عند الطيارين')}<div class="wallet-metric"><span>سجل الصرف</span><strong>محفوظ</strong><small>تفاصيل التسويات في حركة الصرف والسجل</small></div></div><div class="wallet-driver-list">${wallets.map(({driver:d,w})=>`<details class="wallet-driver-card"><summary><span class="wallet-avatar">${esc((d.name||'ط').trim().charAt(0))}${d.photo?`<img src="${esc(d.photo)}" alt="صورة ${esc(d.name)}" loading="lazy" onerror="this.remove()">`:''}</span><span class="wallet-driver-title"><strong>${esc(d.name)}</strong><small>${esc(d.email||'بريد لم يُضف بعد')} · رقم الطيار #${d.id}</small></span><span class="wallet-driver-balance"><small>رصيده الحالي</small><strong>${ledgerCurrency(w.balance)}</strong></span><span class="wallet-chevron">⌄</span></summary><div class="wallet-driver-body"><div class="wallet-driver-stats">${metric('مستحق الطيار',w.balance,'المتبقي للصرف')}<div class="wallet-metric"><span>حالة الحساب</span><strong>${Math.abs(w.balance)+Math.abs(w.commission_due)+Math.abs(w.cash_due)<.001?'تمت التسوية':'قيد التسوية'}</strong><small>العمليات السابقة في الأرشيف</small></div>${metric('حصة ولعه',w.commission_due,'قائمة للتسوية')}${metric('عهدة الكاش',w.cash_due,'لم تسوَّ بعد')}</div><details class="wallet-actions"><summary>⚙ إدارة الرصيد والتسوية</summary><div class="wallet-private"><p class="muted">كل إجراء يسجل في سجل المراجعة ويحتاج كلمة السر وسببًا واضحًا.</p><div class="wallet-fields"><label>المبلغ (+ إضافة / − خصم)<input id="wallet-amount-${d.id}" type="number" step="0.01" placeholder="مثلاً 50 أو -50"></label><label>سبب العملية أو بيانات استلام الفلوس<input id="wallet-reason-${d.id}" maxlength="300"></label><label>كلمة سر لوحة التحكم<input id="wallet-password-${d.id}" type="password" autocomplete="current-password"></label></div><div class="wallet-action-buttons"><button onclick="changeWallet(${d.id},'adjust')">إضافة / خصم</button><button onclick="changeWallet(${d.id},'cash')">تسجيل استلام الكاش والمديونية</button><button onclick="changeWallet(${d.id},'pay')">تسجيل صرف المستحقات</button><button class="wallet-settle-button" onclick="settleDriverWallet(${d.id})">تسوية كل مبالغ الطيار وتصفيرها</button></div><label>بريد الطيار المرتبط بالمحفظة<input id="wallet-email-${d.id}" type="email" value="${esc(d.email||'')}"></label><button class="secondary" onclick="changeWallet(${d.id},'identity')">حفظ بريد الطيار</button><p id="wallet-status-${d.id}" role="status"></p></div></details><details class="wallet-history"><summary>سجل المشاوير · ${w.entries.length}</summary><div class="wallet-history-list">${w.entries.map(o=>`<div class="wallet-history-row"><strong>طلب #${o.id}</strong><span>حصة ولعه ${ledgerCurrency(o.commission_cents/100)} (${o.commission_percent}%)</span><span>صافي الطيار ${ledgerCurrency(o.driver_earning_cents/100)}</span><b>${o.driver_earning_paid?'تم الصرف':'بانتظار الصرف'}</b></div>`).join('')||'<p class="muted">لا توجد مشاوير مكتملة.</p>'}</div></details><details class="wallet-history"><summary>التعديلات والتسويات · ${w.adjustments.length+w.audit.length}</summary><div class="wallet-history-list">${w.adjustments.map(a=>`<div class="wallet-history-row"><strong>${ledgerCurrency(a.amount_cents/100)}</strong><span>${esc(a.reason)}</span><span>${esc(a.at)}</span><b>${a.settled?'تمت التسوية':'قائم'}</b></div>`).join('')}${w.audit.map(a=>{let detail;try{detail=JSON.parse(a.details)}catch{return ''}return `<div class="wallet-history-row"><strong>${esc({adjust:'تعديل الرصيد',cash:'استلام الكاش',pay:'صرف المستحقات',settle:'تصفير بالتسوية',identity:'ربط البريد'}[a.action]||a.action)}</strong><span>${esc(a.at)} · ${esc(detail.intent.reason)}</span><span>قبل ${ledgerCurrency(detail.before.balance)} · بعد ${ledgerCurrency(detail.after.balance)}</span></div>`}).join('')||'<p class="muted">لا توجد تسويات جديدة.</p>'}</div></details></div></details>`).join('')||'<div class="card">أضف حسابات الطيارين أولًا.</div>'}</div></section>`}
async function unlockWallets(){const input=$('wallet-unlock-password'),wallet_password=input.value;input.value='';try{await featureAPI('admin/wallet/unlock',{wallet_password});await refresh();setTimeout(()=>{if(state&&tab==='admin'){state.wallet_unlocked=false;state.driver_wallets={};if(['admin-wallets','admin-cash'].includes(adminPage))render()}},300000)}catch(e){if($('wallet-unlock-status'))$('wallet-unlock-status').textContent=e.message}}
async function lockWallets(){try{await featureAPI('admin/wallet/lock',{});await refresh()}catch(e){alert(e.message)}}
function settleDriverWallet(id){if(!confirm('تأكيد استلام وتسوية كل مستحقات الطيار وعهدة الكاش وحصة ولعه؟ سيتم تصفير المبالغ الحالية وتبقى تفاصيلها في حركة الصرف والسجل.'))return;const reason=$('wallet-reason-'+id);if(reason&&!reason.value.trim())reason.value='تسوية كاملة بعد استلام وسداد المستحقات';changeWallet(id,'settle')}
const walletRequests=new Map(),walletBusy=new Set();
async function changeWallet(id,action){if(walletBusy.has(id))return;const reason=$('wallet-reason-'+id).value.trim(),amount=$('wallet-amount-'+id).value,email=$('wallet-email-'+id).value,wallet_password=$('wallet-password-'+id).value;$('wallet-password-'+id).value='';if(!wallet_password)return $('wallet-status-'+id).textContent='اكتب كلمة سر لوحة التحكم لكل عملية';if(reason.length<3)return $('wallet-status-'+id).textContent='اكتب سبب التعديل أو التسوية';if(['settle','cash','pay'].includes(action)&&!confirm(action==='settle'?'تأكيد تسوية المستحقات والكاش والمديونية بالكامل بعد استلام أو صرف الفلوس؟':'تأكيد تسجيل استلام أو صرف الفلوس بالفعل؟'))return;const intent=JSON.stringify({id,action,reason,amount,email});let request_id=walletRequests.get(intent);if(!request_id){request_id=crypto.randomUUID();walletRequests.set(intent,request_id)}walletBusy.add(id);try{await featureAPI('admin/wallet/change',{driver_id:id,action,reason,amount,email,wallet_password,request_id});walletRequests.delete(intent);await refresh();alert('تم تسجيل التعديل وتحديث محفظة الطيار.')}catch(e){if($('wallet-status-'+id))$('wallet-status-'+id).textContent=e.message}finally{walletBusy.delete(id)}}
let archiveOrderId=null,archiveMessages=[],archiveAfter=0,archiveHasMore=false,archiveLoading=false,archiveSearch='';
let selectedLedgerDay=null;
function ledgerOrders(day){return (state.orders||[]).filter(o=>cairoTripDate(o.created_at)===day)}
function ledgerMoney(orders,field,predicate=()=>true){return orders.filter(predicate).reduce((sum,o)=>sum+Number(o[field]||0),0)}
function ledgerCurrency(value){return new Intl.NumberFormat('ar-EG',{minimumFractionDigits:2,maximumFractionDigits:2}).format(Number(value)||0)+' جنيه'}
function openDailyOrder(id){const o=state.orders.find(x=>x.id===id);if(!o)return;closeDriverDialog('driver-trip-dialog');let dialog=document.createElement('dialog');dialog.id='driver-trip-dialog';dialog.className='admin-trip-dialog';dialog.innerHTML=`<div class="admin-trip-dialog-head"><strong>تفاصيل الطلب #${o.id}</strong><button class="secondary" onclick="closeDriverDialog('driver-trip-dialog')">إغلاق ✕</button></div><div class="admin-trip-dialog-body"><button class="driver-chat-open" onclick="openDriverChat(${o.id})">💬 عرض الرسائل (${Number(state.chat_counts?.[String(o.id)]||0)})</button>${tripDetails(o,'admin')}</div>`;document.body.append(dialog);dialog.addEventListener('close',()=>dialog.remove());dialog.showModal()}
function adminDailyLedger(){const today=new Intl.DateTimeFormat('en-GB',{timeZone:'Africa/Cairo',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date()),part=k=>today.find(x=>x.type===k)?.value||'',todayKey=`${part('year')}-${part('month')}-${part('day')}`,days=[...new Set([todayKey,...(state.orders||[]).map(o=>cairoTripDate(o.created_at))])].sort().reverse(),day=selectedLedgerDay&&days.includes(selectedLedgerDay)?selectedLedgerDay:todayKey,orders=ledgerOrders(day),completed=orders.filter(o=>o.status==='delivered'),commission=ledgerMoney(completed,'commission_cents')/100,commissionDue=ledgerMoney(completed,'commission_cents',o=>!o.commission_settled)/100,driverEarnings=ledgerMoney(completed,'driver_earning_cents')/100,driverDue=ledgerMoney(completed,'driver_earning_cents',o=>!o.driver_earning_paid)/100,cashDue=ledgerMoney(completed,'total',o=>o.payment==='cash'&&o.cash_collected&&!o.cash_settled),customerIds=[...new Set(orders.map(o=>o.user_id))],driverIds=[...new Set(orders.map(o=>o.driver_id).filter(Boolean))];const stat=(title,value,detail)=>`<article class="ledger-stat"><span>${title}</span><strong>${value}</strong><small>${detail}</small></article>`;return `<div class="ledger-page"><div class="ledger-heading"><div><span class="ledger-eyebrow">تقارير التشغيل</span><h2>حركة الأيام</h2><p>اختار يومًا لعرض الطلبات والحسابات الخاصة به.</p></div><span class="ledger-day-count">${days.length} يوم</span></div><div class="ledger-days">${days.map(d=>{let all=ledgerOrders(d),done=all.filter(o=>o.status==='delivered');return `<button class="ledger-day ${day===d?'active':''}" data-staff-read onclick="selectedLedgerDay='${d}';render()"><span>${d===todayKey?'اليوم · ':''}${esc(new Date(d+'T12:00:00Z').toLocaleDateString('ar-EG',{timeZone:'Africa/Cairo',weekday:'long',day:'numeric',month:'long',year:'numeric'}))}</span><strong>${all.length} طلب</strong><small>${done.length} مكتمل · حصة ولعه ${ledgerCurrency(ledgerMoney(done,'commission_cents')/100)}</small></button>`}).join('')}</div><section class="card ledger-detail"><div class="section-heading"><h2>تفاصيل ${esc(day)}</h2><span class="tag">${orders.length} طلب</span></div><p class="muted">الحسابات حسب يوم إنشاء الطلب بتوقيت مصر. «المتبقي» يعكس حالة التسوية الحالية لهذه الطلبات.</p><div class="ledger-stats">${stat('الطلبات',''+orders.length,`${completed.length} تم تسليمها · ${orders.length-completed.length} أخرى`)}${stat('قيمة الطلبات المكتملة',ledgerCurrency(ledgerMoney(completed,'total')),'لا تشمل الملغي والجاري')}${stat('حصة ولعه',ledgerCurrency(commission),`المتبقي من حصة ولعه ${ledgerCurrency(commissionDue)}`)}${stat('مستحق الطيارين',ledgerCurrency(driverEarnings),`المتبقي للصرف ${ledgerCurrency(driverDue)}`)}${stat('كاش عند الطيارين',ledgerCurrency(cashDue),'محصل ولم تسجل تسويته')}</div><div class="ledger-columns"><section><h3>العملاء · ${customerIds.length}</h3>${customerIds.map(id=>{let own=orders.filter(o=>o.user_id===id),done=own.filter(o=>o.status==='delivered');return `<details class="ledger-person"><summary><strong>${esc(own[0].customer)}</strong><span>${own.length} طلب · مكتمل ${done.length} · ${ledgerCurrency(ledgerMoney(done,'total'))}</span></summary>${dailyPersonCounter('customer',id,day,own,todayKey)}${own.map(o=>ledgerOrderButton(o)).join('')}</details>`}).join('')||'<p class="muted">لا توجد طلبات في هذا اليوم.</p>'}</section><section><h3>الطيارون · ${driverIds.length}</h3>${driverIds.map(id=>{let own=orders.filter(o=>o.driver_id===id),done=own.filter(o=>o.status==='delivered'),driver=state.drivers.find(d=>d.id===id),km=(state.daily_distances||[]).find(x=>x.driver_id===id&&x.day===day)?.meters||0;return `<details class="ledger-person"><summary><strong>${esc(driver?.name||own[0].driver_name||'طيار سابق')}</strong><span>${own.length} طلب · حصة ولعه ${ledgerCurrency(ledgerMoney(done,'commission_cents')/100)} · مستحق ${ledgerCurrency(ledgerMoney(done,'driver_earning_cents')/100)}</span></summary>${dailyPersonCounter('driver',id,day,own,todayKey)}<p class="muted">المتبقي للصرف ${ledgerCurrency(ledgerMoney(done,'driver_earning_cents',o=>!o.driver_earning_paid)/100)} · كاش لم يُسوَّ ${ledgerCurrency(ledgerMoney(done,'total',o=>o.payment==='cash'&&o.cash_collected&&!o.cash_settled))} · GPS ${(Number(km)/1000).toFixed(2)} كم</p>${own.map(o=>ledgerOrderButton(o)).join('')}</details>`}).join('')||'<p class="muted">لا توجد مشاوير مسندة في هذا اليوم.</p>'}</section></div></section></div>`}
function dailyPersonCounter(role,id,day,orders,today){const reset=(state.daily_resets||[]).find(r=>r.person_type===role&&r.person_id===id&&r.day===day),since=reset?orders.filter(o=>String(o.created_at)>reset.at):orders;return `<div class="daily-counter"><span>عداد اليوم: <strong>${since.length}</strong> طلب${reset?` · آخر تصفير ${esc(new Date(reset.at).toLocaleTimeString('ar-EG',{timeZone:'Africa/Cairo'}))}`:''}</span>${day===today?`<button class="secondary" onclick="resetDailyPerson('${role}',${id},'${day}')">تصفير عدد الطلبات فقط</button>${role==='driver'?`<button onclick="openAdminPage('admin-wallets')">تسوية محفظة الطيار وتصفير المبالغ</button>`:''}`:''}</div>`}
async function resetDailyPerson(role,id,day){if(!confirm('تصفير عداد اليوم لهذا الحساب؟ ستبقى الطلبات والتسويات محفوظة في السجل.'))return;try{await featureAPI('admin/daily/reset',{person_type:role,person_id:id,day});await refresh()}catch(e){alert(e.message)}}
let activityFrom='',activityTo='',activityLoaded=false,activityData={orders:[],events:[],settlements:[],resets:[],rewards:[]},activitySearch='',activityOffset=0,activityHasMore=false;
function activityDefaultDates(){if(activityFrom&&activityTo)return;let parts=new Intl.DateTimeFormat('en-GB',{timeZone:'Africa/Cairo',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date()),part=k=>parts.find(x=>x.type===k)?.value||'';activityTo=`${part('year')}-${part('month')}-${part('day')}`;activityFrom=`${part('year')}-${part('month')}-01`}
async function loadAdminActivity(more=false){activityDefaultDates();if(!more){activityOffset=0;activityData={orders:[],events:[],settlements:[],resets:[],rewards:[]}}const box=$('activity-status');if(box)box.textContent='جارٍ تحميل الحركات…';try{let data=await featureAPI('admin/activity',{from:activityFrom,to:activityTo,offset:activityOffset});for(let key of ['orders','events','settlements','resets','rewards'])activityData[key].push(...(data[key]||[]));activityHasMore=!!data.has_more;activityOffset+=1000;activityLoaded=true;render()}catch(e){if($('activity-status'))$('activity-status').textContent=e.message}}
function activityNameKey(value){return String(value||'').normalize('NFKC').toLowerCase().replace(/[\u064B-\u065F\u0670ـ]/g,'').replace(/[أإآٱ]/g,'ا').replace(/ى/g,'ي').replace(/ة/g,'ه').replace(/\s+/g,' ').trim()}
function updateActivitySearch(value){activitySearch=value;const input=$('activity-search'),cursor=input?.selectionStart;render();const next=$('activity-search');if(next){next.focus();try{next.setSelectionRange(cursor,cursor)}catch{}}}
function adminActivityPage(){activityDefaultDates();const settlementLabels={adjust:'تعديل الرصيد',cash:'استلام الكاش والمديونية',pay:'صرف مستحقات الطيار',settle:'تسوية وتصفير',identity:'تعديل بريد الطيار'},rows=[...activityData.orders.map(o=>({day:cairoTripDate(o.at),at:o.at,kind:'order',name:o.customer+' · '+(o.driver_name||'لم يُسند'),title:'طلب #'+o.id+' · '+(status[o.status]||o.status),detail:ledgerCurrency(o.total),id:o.id})),...activityData.events.map(x=>({day:cairoTripDate(x.at),at:x.at,kind:'event',name:x.customer+' · '+(x.driver_name||'لم يُسند'),title:x.action,detail:'طلب #'+x.order_id,id:x.order_id})),...activityData.settlements.map(x=>{let d={};try{d=JSON.parse(x.details)}catch{}return {day:cairoTripDate(x.at),at:x.at,kind:'money',name:x.driver_name,title:settlementLabels[x.action]||x.action,detail:`${d.intent?.reason||''} · مستحق ${ledgerCurrency(d.before?.balance)} ← ${ledgerCurrency(d.after?.balance)} · حصة ولعه ${ledgerCurrency(d.before?.commission_due)} ← ${ledgerCurrency(d.after?.commission_due)} · عهدة الكاش ${ledgerCurrency(d.before?.cash_due)} ← ${ledgerCurrency(d.after?.cash_due)}`}}),...activityData.resets.map(x=>({day:cairoTripDate(x.at),at:x.at,kind:'reset',name:x.name||'#'+x.person_id,title:'تصفير عدد طلبات '+(x.person_type==='driver'?'الطيار':'العميل'),detail:'يوم '+x.day+' · المعاملات المالية محفوظة'})),...activityData.rewards.map(x=>({day:cairoTripDate(x.at),at:x.at,kind:'reward',name:x.name,title:x.kind==='bonus'?'بونص طيار':'خصم عميل',detail:ledgerCurrency(x.amount_cents/100)}))].filter(x=>!activitySearch.trim()||[x.name,x.title,x.detail,x.id].some(v=>activityNameKey(v).includes(activityNameKey(activitySearch)))).sort((a,b)=>String(b.at).localeCompare(String(a.at))),days=[...new Set(rows.map(r=>r.day))],label={order:'طلب',event:'حركة طلب',money:'معاملة مالية',reset:'تصفير عداد',reward:'مكافأة'},icon={order:'▤',event:'↗',money:'ج',reset:'↺',reward:'★'};return `<section class="activity-page"><div class="admin-section-intro"><span>أرشيف العمليات</span><h2>حركة الصرف والسجل</h2><p>كل يوم مستقل بحركاته؛ التسويات والتصفير لا يحذفان الطلبات أو تاريخ المعاملات.</p></div><div class="activity-summary"><article><span>حركات معروضة</span><strong>${rows.length}</strong><small>حسب الفترة والبحث</small></article><article><span>معاملات مالية</span><strong>${rows.filter(r=>r.kind==='money').length}</strong><small>صرف وتسويات وتعديل</small></article><article><span>أيام بها حركة</span><strong>${days.length}</strong><small>افتح يومًا لمراجعة تفاصيله</small></article></div><div class="card activity-filter"><label>من يوم<input id="activity-from" type="date" value="${esc(activityFrom)}"></label><label>إلى يوم<input id="activity-to" type="date" value="${esc(activityTo)}"></label><button onclick="activityFrom=$('activity-from').value;activityTo=$('activity-to').value;loadAdminActivity()">عرض الفترة</button><form class="activity-query activity-search-form" onsubmit="event.preventDefault();activitySearch=this.querySelector('input').value;render()"><label for="activity-search">بحث عن طيار أو عميل أو عملية</label><div class="activity-search-field"><input id="activity-search" type="search" oninput="updateActivitySearch(this.value)" list="activity-driver-names" value="${esc(activitySearch)}" placeholder="اسم الطيار، رقم الطلب أو نوع العملية…"><datalist id="activity-driver-names">${(state.drivers||[]).map(d=>`<option value="${esc(d.name)}"></option>`).join('')}</datalist><button type="submit" data-staff-read aria-label="بحث في الحركات"><svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/></svg><span>بحث</span></button></div></form></div><p id="activity-status" role="status" class="activity-status">${activityLoaded?`${rows.length} حركة في النتائج`:'اختر الفترة لعرض الحركات'}</p>${days.map(day=>{let dayRows=rows.filter(r=>r.day===day);return `<details class="activity-day"><summary><span class="activity-day-icon">◷</span><span class="activity-day-title"><strong>${esc(new Date(day+'T12:00:00Z').toLocaleDateString('ar-EG',{timeZone:'Africa/Cairo',weekday:'long',day:'numeric',month:'long',year:'numeric'}))}</strong><small>${dayRows.filter(r=>r.kind==='money').length} معاملة مالية · ${dayRows.filter(r=>r.kind==='order').length} طلب</small></span><b>${dayRows.length} حركة</b><span class="activity-chevron">⌄</span></summary><div>${dayRows.map(r=>`<article class="activity-row ${r.kind}"><span class="activity-symbol">${icon[r.kind]}</span><div><span class="activity-type">${label[r.kind]}</span><strong>${esc(r.title)}</strong><p>${esc(r.name)}</p><small>${esc(r.detail)} · ${esc(new Date(r.at).toLocaleTimeString('ar-EG',{timeZone:'Africa/Cairo',hour:'numeric',minute:'2-digit'}))}</small></div>${r.id?`<button onclick="openDailyOrder(${r.id})">تفاصيل الطلب ↗</button>`:''}</article>`).join('')}</div></details>`}).join('')||'<div class="card empty">لا توجد حركات مطابقة في الفترة المحددة. جرّب توسيع تاريخ البداية والنهاية لعرض حركات الطيار الأقدم.</div>'}${activityHasMore?'<button class="activity-more" onclick="loadAdminActivity(true)">عرض حركات أقدم في الفترة</button>':''}</section>`}
function ledgerOrderButton(o){return `<button class="ledger-order" onclick="openDailyOrder(${o.id})"><strong>#${o.id} · ${esc(status[o.status]||o.status)}</strong><span>${esc(o.customer)} · ${money(o.total)} · ${esc(new Date(o.created_at).toLocaleTimeString('ar-EG',{timeZone:'Africa/Cairo',hour:'numeric',minute:'2-digit'}))}</span><b>التفاصيل والرسائل ←</b></button>`}
function adminChatThreadRows(){let q=archiveSearch.trim().toLowerCase(),threads=(state.chat_threads||[]).filter(t=>!q||[t.order_id,t.customer,t.driver_name].some(v=>String(v||'').toLowerCase().includes(q)));return threads.map(t=>`<button class="card ${archiveOrderId===t.order_id?'on':''}" style="display:block;width:100%;text-align:right;margin:8px 0" onclick="openArchivedChat(${t.order_id})"><strong>طلب #${t.order_id} · ${esc(t.customer)} ↔ ${esc(t.driver_name||'طيار سابق')}</strong><p>${t.message_count} رسالة · ${esc(status[t.status]||t.status)} · ${esc(t.last_at||'')}</p></button>`).join('')||'<p class="muted">لا توجد محادثات مسجلة بهذا البحث.</p>'}
function adminChatArchive(){return `<section class="card"><h2>شات العميل مع الطيار</h2><p>تظهر هنا المحادثات المحفوظة، بما فيها الطلبات المنتهية. هذه الصفحة للمسؤول فقط.</p><label>ابحث باسم العميل أو الطيار أو رقم الطلب<input id="archive-search" value="${esc(archiveSearch)}" oninput="archiveSearch=this.value;$('chat-thread-list').innerHTML=adminChatThreadRows()"></label><div id="chat-thread-list">${adminChatThreadRows()}</div><h3>${archiveOrderId?'محادثة الطلب #'+archiveOrderId:'اختار محادثة لعرض الرسائل'}</h3><div id="archive-messages" class="admin-chat-stream" role="log" aria-label="محادثة العميل والطيار">${archivedChatHTML()}</div><p id="archive-status" role="status"></p><button id="archive-more" onclick="loadArchivedChat()" ${archiveHasMore?'':'hidden'}>عرض الرسائل التالية</button>${archiveOrderId?`<button onclick="openArchivedChat(${archiveOrderId})">تحديث المحادثة</button>`:''}</section>`}

function archivedChatHTML(){return archiveMessages.map(m=>`<article class="admin-message ${m.sender_role==='driver'?'from-driver':'from-customer'}"><span class="chat-author">${m.sender_role==='driver'?'🛵 الطيار':'👤 العميل'} · ${esc(m.sender_name)}</span><p>${esc(m.body)}</p><time datetime="${esc(m.at)}">${esc(new Date(m.at).toLocaleString('ar-EG',{timeZone:'Africa/Cairo',dateStyle:'short',timeStyle:'short'}))}</time></article>`).join('')||'<p class="muted">لا توجد رسائل محفوظة لهذا الطلب.</p>'}
async function openArchivedChat(id){archiveOrderId=id||null;archiveMessages=[];archiveAfter=0;archiveHasMore=false;if(!id){render();return}render();await loadArchivedChat()}
async function loadArchivedChat(){if(!archiveOrderId||archiveLoading)return;archiveLoading=true;const order_id=archiveOrderId;try{const result=await featureAPI('admin/chat/archive',{order_id,after_id:archiveAfter});if(order_id!==archiveOrderId)return;archiveMessages.push(...result.messages);archiveAfter=result.next_id;archiveHasMore=result.has_more;if($('archive-messages'))$('archive-messages').innerHTML=archivedChatHTML();if($('archive-more'))$('archive-more').hidden=!archiveHasMore;if($('archive-status'))$('archive-status').textContent=archiveMessages.length?'تم تحميل المحادثة المحفوظة':'لا توجد رسائل لهذا الطلب'}catch(e){if($('archive-status'))$('archive-status').textContent=e.message}finally{archiveLoading=false}}

async function openAdminPage(id){if(Array.isArray(state.staff_permissions)&&!state.staff_permissions.includes(id))return;if(['admin-wallets','admin-cash'].includes(adminPage)||['admin-wallets','admin-cash'].includes(id)){state.wallet_unlocked=false;state.driver_wallets={};try{await featureAPI('admin/wallet/lock',{})}catch(e){alert(e.message)}}adminPage=id;render();if(id==='admin-chat-archive'){let latest=state.chat_threads?.[0];if(latest)await openArchivedChat(latest.order_id)}if(id==='admin-activity'&&!activityLoaded)await loadAdminActivity()}

function clearPrivateSessionData(){selectedDriverId=null;driverTripDate='';closeDriverDialog('driver-chat-dialog');closeDriverDialog('driver-trip-dialog');closeShiftCamera();archiveOrderId=null;archiveMessages=[];archiveAfter=0;archiveHasMore=false;walletRequests.clear();walletBusy.clear()}

function orderArchivePanel(o){if(archiveOrderId!==o.id)return '';return `<section class="order-archive-box"><div class="order-archive-heading"><div><span>المحادثة المحفوظة</span><h3>سجل الشات · طلب #${o.id}</h3></div><button class="secondary" onclick="archiveOrderId=null;render()" aria-label="إغلاق سجل الشات">إغلاق</button></div><p class="muted">كل رسائل العميل والطيار محفوظة هنا، حتى بعد انتهاء الطلب.</p><div id="archive-messages" class="order-archive-stream admin-chat-stream">${archivedChatHTML()}</div><p id="archive-status" role="status"></p><div class="row"><button id="archive-more" onclick="loadArchivedChat()" ${archiveHasMore?'':'hidden'}>رسائل أقدم / التالية</button><button class="secondary" onclick="openArchivedChat(${o.id})">تحديث الشات</button></div></section>`}
async function openOrderArchive(id){adminPage='admin-orders';await openArchivedChat(id);document.querySelector('.order-archive-box')?.scrollIntoView({behavior:'smooth',block:'center'})}

let shiftCameraStream=null,shiftCameraGeneration=0,shiftPhoto='',shiftSaving=false;
function driverShiftPanel(required=false){const shift=state.driver_shift&&(!state.shift_required||state.shift_second_required||state.shift_review_pending)?state.driver_shift:null;const title=state.shift_review_pending?'انتظار تأكيد صورة الشيفت':state.shift_second_required?'صورة متابعة مطلوبة':required?'ابدأ شيفتك قبل الدخول':'شيفت الطيار';const message=state.shift_review_pending?'<p>تم رفع صورة متابعة الشيفت. التطبيق متوقف مؤقتًا حتى تؤكد الإدارة الصورة من الداشبورد.</p>':state.shift_second_required?'<p>عدّت ٦ ساعات على بداية الشيفت. التقط صورة المتابعة، وبعد رفعها انتظر تأكيد الإدارة لاستئناف العمل.</p>':required?'<p>صورة بداية الشيفت وصورة متابعة بعد ٦ ساعات.</p>':'';return `<section class="card shift-card"><h2>${title}</h2>${message}${shift?`<p>بدأ الشيفت ${esc(new Date(shift.started_at).toLocaleString('ar-EG',{timeZone:'Africa/Cairo'}))}</p><p>صورة بداية الشيفت محفوظة لدى الإدارة.</p>${state.shift_review_pending?'<p>الصورة الثانية مرفوعة وتنتظر المراجعة.</p>':state.shift_second_required?'<button onclick="openShiftCamera(true)">📷 التقط صورة المتابعة الآن</button>':shift.second_photo_at?'<p>الصورة الثانية مؤكدة.</p>':'<p>الصورة الثانية مطلوبة بعد ٦ ساعات من البداية.</p>'}${required?'':'<button class="secondary" onclick="endDriverShift()">إنهاء الشيفت</button>'}`:`<p>اضغط بدء الشيفت، اسمح بالكاميرا، ثم التقط صورة واضحة لوجهك. الصورة ووقت البداية يظهران للمسؤول للمراجعة.</p><button onclick="openShiftCamera()">📷 بدء الشيفت</button>`}</section>`}
function closeShiftCamera(){shiftCameraGeneration++;shiftCameraStream?.getTracks().forEach(t=>t.stop());shiftCameraStream=null;shiftPhoto='';document.getElementById('shift-camera-dialog')?.remove()}
let secondShiftPhoto=false;
async function openShiftCamera(second=false){secondShiftPhoto=second;closeShiftCamera();const generation=shiftCameraGeneration;const dialog=document.createElement('dialog');dialog.id='shift-camera-dialog';dialog.className='shift-camera-dialog';dialog.innerHTML=`<h2>${second?'صورة منتصف الشيفت':'صورة بداية الشيفت'}</h2><p>اسمح بالكاميرا وخلّي وجهك واضحًا داخل الصورة.</p><video id="shift-camera-video" autoplay playsinline muted></video><img id="shift-camera-preview" class="shift-selfie" alt="صورة بداية الشيفت" hidden><p id="shift-camera-status" role="status">جاري طلب السماح بالكاميرا…</p><button id="shift-capture" onclick="captureShiftPhoto()" disabled>التقاط صورة الوجه</button><button id="shift-save" onclick="saveDriverShift()" hidden>تأكيد الصورة وبدء الشيفت</button><button id="shift-retry" onclick="openShiftCamera(secondShiftPhoto)" hidden>إعادة التصوير / طلب السماح</button><button class="secondary" onclick="closeShiftCamera()">إلغاء</button>`;dialog.addEventListener('cancel',e=>{e.preventDefault();closeShiftCamera()});document.body.append(dialog);dialog.showModal();try{if(!navigator.mediaDevices?.getUserMedia)throw Error('الكاميرا غير متاحة هنا. استخدم تطبيق الطيار الجديد أو Chrome.');const stream=await navigator.mediaDevices.getUserMedia({audio:false,video:{facingMode:'user',width:{ideal:720},height:{ideal:720}}});if(generation!==shiftCameraGeneration||!dialog.isConnected){stream.getTracks().forEach(t=>t.stop());return}shiftCameraStream=stream;$('shift-camera-video').srcObject=stream;await $('shift-camera-video').play();$('shift-capture').disabled=false;$('shift-camera-status').textContent='الكاميرا جاهزة. التقط صورة وجهك.'}catch(e){if(generation!==shiftCameraGeneration)return;$('shift-camera-status').textContent=e.name==='NotAllowedError'?'لم يتم السماح بالكاميرا. اضغط إعادة المحاولة واختر السماح عند ظهور الطلب.':e.message;$('shift-retry').hidden=false}}
function captureShiftPhoto(){const video=$('shift-camera-video');if(!video?.videoWidth)return;const canvas=document.createElement('canvas');const scale=Math.min(1,720/video.videoWidth);canvas.width=Math.round(video.videoWidth*scale);canvas.height=Math.round(video.videoHeight*scale);canvas.getContext('2d').drawImage(video,0,0,canvas.width,canvas.height);shiftPhoto=canvas.toDataURL('image/jpeg',.8);$('shift-camera-preview').src=shiftPhoto;$('shift-camera-preview').hidden=false;video.hidden=true;$('shift-capture').hidden=true;$('shift-save').hidden=false;$('shift-retry').hidden=false;shiftCameraStream?.getTracks().forEach(t=>t.stop());shiftCameraStream=null;$('shift-camera-status').textContent='راجع الصورة، ثم أكد بدء الشيفت.'}
async function saveDriverShift(){if(shiftSaving||!shiftPhoto)return;shiftSaving=true;$('shift-save').disabled=true;try{await featureAPI(secondShiftPhoto?'driver/shift/second':'driver/shift/start',{selfie:shiftPhoto});closeShiftCamera();driverView='trips';await refresh()}catch(e){if($('shift-camera-status'))$('shift-camera-status').textContent=e.message;if($('shift-save'))$('shift-save').disabled=false}finally{shiftSaving=false}}
async function endDriverShift(){if(!await window.appConfirm('إنهاء الشيفت وإيقاف استقبال طلبات جديدة؟',{title:'إنهاء الشيفت',confirmText:'إنهاء الشيفت',tone:'danger'}))return;try{await featureAPI('driver/shift/end',{});await refresh()}catch(e){alert(e.message)}}
let shiftReviewArchive=false;
function adminPaymentNumbers(){return `<section class="card"><h2>أرقام الدفع</h2><p>غيّر رقم المحفظة وحساب إنستاباي كل واحد لوحده. يظهر الجديد للعميل في صفحة التحويل بعد الحفظ.</p><label for="s-wallet">رقم المحفظة</label><input id="s-wallet" inputmode="tel" value="${esc(state.settings.wallet||'')}" placeholder="مثلاً 01xxxxxxxxx"><label for="s-instapay">رقم أو حساب إنستاباي</label><input id="s-instapay" value="${esc(state.settings.instapay||'')}" placeholder="رقم الهاتف أو عنوان الحساب"><p id="payment-number-status" role="status"></p><button onclick="savePaymentNumbers()">حفظ أرقام الدفع</button></section>`}
async function savePaymentNumbers(){const button=document.querySelector('#admin-workspace button[onclick="savePaymentNumbers()"]');if(button)button.disabled=true;try{await featureAPI('settings',{wallet:$('s-wallet').value.trim(),instapay:$('s-instapay').value.trim()});await refresh();const status=$('payment-number-status');if(status)status.textContent='تم حفظ الأرقام. تظهر للعميل في صفحة التحويل.'}catch(e){const status=$('payment-number-status');if(status)status.textContent=e.message}finally{if(button?.isConnected)button.disabled=false}}
function adminFeatured(){const people=state.featured_people||[],customers=people.filter(p=>p.role==='customer').sort((a,b)=>b.completed-a.completed),drivers=people.filter(p=>p.role==='driver').sort((a,b)=>b.featured-a.featured||b.average-a.average);const card=p=>`<article class="card"><strong>${esc(p.name)} ${p.featured?'⭐ مميز':''}</strong><p>${p.role==='customer'?'طلبات مكتملة: '+p.completed+' · ':''}تقييم ${p.average??'—'} / ٥ من ${p.rating_count} تقييم</p><button onclick="setFeatured(${p.id},${p.featured?0:1})">${p.featured?'إلغاء التمييز':'تمييز'}</button><label>${p.role==='driver'?'بونص للمحفظة':'خصم على طلب منتجات كاش القادم'}<input id="reward-${p.id}" type="number" min=".01" max="10000" step=".01" placeholder="المبلغ بالجنيه"></label><button onclick="giveFeaturedReward(${p.id},'${p.role==='driver'?'bonus':'discount'}')">إضافة</button></article>`;return `<section class="card"><h2>تقييمات العملاء · الأكثر طلبًا</h2><p>مرتبون بعدد الطلبات المسلّمة. يمكنك تمييز العميل وإضافة خصم له.</p>${customers.map(card).join('')||'<p>لا توجد طلبات مكتملة بعد.</p>'}<h2>الطيارون المميزون</h2><p>الطيار المميز له أولوية في الطلبات من ٣٥ جنيهًا عند توافره، حتى لو كان أبعد.</p>${drivers.map(card).join('')||'<p>لا يوجد طيارون بعد.</p>'}</section>`}
async function setFeatured(id,featured){try{await featureAPI('admin/featured',{user_id:id,action:'mark',featured});await refresh()}catch(e){alert(e.message)}}
async function giveFeaturedReward(id,action){const amount=Number($('reward-'+id)?.value);if(!Number.isFinite(amount)||amount<.01||amount>10000)return alert('اكتب مبلغًا صحيحًا');if(!confirm('تأكيد إضافة '+amount+' جنيه؟'))return;try{await featureAPI('admin/featured',{user_id:id,action,amount});await refresh()}catch(e){alert(e.message)}}
function adminDriverShifts(){const shifts=(state.driver_shifts||[]).filter(s=>shiftReviewArchive?(s.review_status!=='pending'&&(!s.second_photo_at||s.second_review_status!=='pending')):(s.review_status==='pending'||(s.second_photo_at&&s.second_review_status==='pending')));return `<section class="shift-review-page"><div class="admin-section-intro"><span>مراجعة الهوية</span><h2>شيفتات الطيارين</h2><p>راجع صور بداية الشيفت والصورة الثانية، وسجل التأكيد أو الإنذار.</p></div><div class="shift-review-tabs"><button class="${!shiftReviewArchive?'on':''}" data-staff-read onclick="shiftReviewArchive=false;render()">تنتظر المراجعة</button><button class="${shiftReviewArchive?'on':''}" data-staff-read onclick="shiftReviewArchive=true;render()">أرشيف التأكيدات والإنذارات</button></div><div class="shift-review-grid">${shifts.map(s=>`<article class="card shift-review-card"><div class="shift-review-head"><div class="wallet-avatar">${s.photo?`<img src="${esc(s.photo)}" alt="صورة ${esc(s.name)}" onerror="this.remove()">`:esc((s.name||'ط').charAt(0))}</div><div><h3>${esc(s.name)}</h3><small>شيفت #${s.id} · ${esc(new Date(s.started_at).toLocaleString('ar-EG',{timeZone:'Africa/Cairo'}))}</small><p>${esc(s.email||'بدون بريد')}</p></div></div><span class="tag">${s.review_status==='confirmed'?'تم تأكيد الهوية':s.review_status==='warned'?'إنذار الهوية':'بانتظار المراجعة'}${s.restored_at?' · أعيد تفعيل الحساب':''}</span><div class="shift-photo-actions"><button onclick="viewShiftPhoto(${s.id})">📷 صورة بداية الشيفت</button>${s.second_photo_at?`<button onclick="viewShiftPhoto(${s.id},true)">📷 الصورة الثانية</button>`:''}</div><div id="shift-photo-${s.id}"></div>${s.second_photo_at?`<div id="shift-photo-${s.id}-second"></div><p class="muted">الصورة الثانية: ${esc(new Date(s.second_photo_at).toLocaleString('ar-EG',{timeZone:'Africa/Cairo'}))} · ${s.second_review_status==='confirmed'?'تم تأكيدها':s.second_review_status==='warned'?'إنذار':'تنتظر المراجعة'}</p>${s.second_review_status==='pending'?`<div class="shift-decision"><button onclick="reviewDriverShift(${s.id},'confirm_second')">تأكيد الصورة الثانية</button><button class="secondary" onclick="reviewDriverShift(${s.id},'warn_second')">إنذار وإيقاف</button></div>`:''}`:''}${s.review_status==='pending'?`<div class="shift-decision"><button onclick="reviewDriverShift(${s.id},'confirm')">تأكيد الهوية</button><button class="secondary" onclick="reviewDriverShift(${s.id},'warn')">إنذار وإيقاف الحساب</button></div>`:''}${s.identity_blocked_shift===s.id?`<p class="muted">الحساب موقوف. راجع الطلبات الجارية قبل إعادة التفعيل.</p><button onclick="reviewDriverShift(${s.id},'restore')">إعادة تفعيل الحساب</button>`:''}</article>`).join('')||'<div class="card empty">لا توجد صور في هذا العرض.</div>'}</div></section>`}
async function reviewDriverShift(id,action){if(!confirm(action.startsWith('warn')?'إيقاف حساب الطيار بسبب عدم تطابق الهوية؟ لن يتمكن من استخدام التطبيق حتى تعيد تفعيله.':action==='restore'?'تأكدت من الطيار الصحيح؟ سيحتاج صورة شيفت جديدة بعد إعادة التفعيل.':'تأكيد هوية الطيار ونقل الصورة للأرشيف؟'))return;try{await featureAPI('admin/shift/review',{id,action});await refresh()}catch(e){alert(e.message)}}

async function viewShiftPhoto(id,second=false){try{const r=await featureAPI('admin/shift/photo',{id,second});const img=document.createElement('img');img.className='shift-selfie';img.alt='صورة وجه الطيار في بداية الشيفت';img.src=r.photo;const root=$('shift-photo-'+id+(second?'-second':''));if(root)root.replaceChildren(img)}catch(e){alert(e.message)}}
window.addEventListener('pagehide',closeShiftCamera);

const teamSections=[['admin-overview','ملخص الإدارة'],['admin-orders','الطلبات'],['admin-driver-list','الطيارون'],['admin-driver-shifts','الشيفتات'],['admin-map-section','الخريطة'],['admin-daily','حركة الأيام'],['admin-activity','حركة الصرف والسجل'],['admin-products','المنتجات'],['admin-merchants','المحلات'],['admin-categories','الأقسام'],['admin-delivery-rate','أسعار التوصيل'],['admin-commission','نسب ولعه'],['admin-services','الخدمات'],['admin-ratings','التقييمات'],['admin-featured','المميزون'],['admin-support','الدعم']];
function adminTeamPage(){return `<section class="team-page"><div class="admin-section-intro"><span>إدارة الوصول</span><h2>أعضاء الفريق</h2><p>كل عضو يدخل باسم مستخدم وكلمة مرور. تحدد له الأقسام التي يطّلع عليها، بصلاحية عرض فقط. المحفظة والإعدادات والتعديل للمسؤول الرئيسي.</p></div><div class="team-layout"><form class="card team-form" onsubmit="event.preventDefault();createTeamMember()"><h3>إضافة عضو فريق</h3><label>اسم الموظف<input id="team-name" required maxlength="80"></label><label>اسم المستخدم<input id="team-username" required autocomplete="off" maxlength="32"></label><label>كلمة المرور · 10 أحرف على الأقل<input id="team-password" type="password" required minlength="10" autocomplete="new-password"></label><h4>الأقسام المسموح بعرضها</h4><div class="team-permissions">${teamSections.map(([id,label])=>`<label><input type="checkbox" name="team-section" value="${id}"> ${label}</label>`).join('')}</div><button type="submit">حفظ العضو</button><p id="team-status" role="status"></p></form><div class="team-members">${(state.staff_members||[]).map(m=>{let allowed=[];try{allowed=JSON.parse(m.permissions)}catch{}return `<article class="card team-member"><div class="team-member-head"><span class="team-avatar">${esc(m.name.charAt(0))}</span><div><strong>${esc(m.name)}</strong><small>@${esc(m.username)} · ${m.disabled?'موقوف':'نشط'}</small></div></div><div class="team-permissions">${teamSections.map(([id,label])=>`<label><input type="checkbox" data-member="${m.id}" value="${id}" ${allowed.includes(id)?'checked':''}> ${label}</label>`).join('')}</div><div class="row"><button onclick="saveTeamMember(${m.id})">حفظ الصلاحيات</button><button class="secondary" onclick="toggleTeamMember(${m.id},'${m.disabled?'enable':'disable'}')">${m.disabled?'تفعيل':'إيقاف الدخول'}</button></div></article>`}).join('')||'<div class="card empty">مافيش موظفين مضافين حتى الآن.</div>'}</div></div></section>`}
async function createTeamMember(){let button=document.querySelector('.team-form button[type=submit]');button.disabled=true;try{await featureAPI('admin/team',{action:'create',name:$('team-name').value.trim(),username:$('team-username').value.trim(),password:$('team-password').value,permissions:[...document.querySelectorAll('[name=team-section]:checked')].map(x=>x.value)});await refresh()}catch(e){$('team-status').textContent=e.message}finally{if(button.isConnected)button.disabled=false}}
async function saveTeamMember(id){try{await featureAPI('admin/team',{action:'update',id,permissions:[...document.querySelectorAll('[data-member="'+id+'"]:checked')].map(x=>x.value)});await refresh()}catch(e){alert(e.message)}}
async function toggleTeamMember(id,action){if(!confirm(action==='disable'?'إيقاف دخول هذا الموظف الآن؟':'تفعيل حساب الموظف؟'))return;try{await featureAPI('admin/team',{action,id});await refresh()}catch(e){alert(e.message)}}
function enforceStaffReadOnly(){if(!Array.isArray(state?.staff_permissions))return;document.querySelectorAll('#admin-workspace button').forEach(b=>{const h=b.getAttribute('onclick')||'';if(!b.hasAttribute('data-staff-read')&&!/^(?:openDailyOrder|openDriverTrip|openDriverTrips|openDriverChat|openArchivedChat|loadAdminActivity|viewShiftPhoto|render|refreshAdminProductList|openOrderArchive|openAdminPage|showAllDriverTrips|clearDriverTripDate|closeDriverDialog|loadDriverChat|loadOrderChat|viewOrderProof)\(/.test(h)){b.disabled=true;b.title='للعرض فقط'}})}
function adminProductStudio(){const active=state.products.filter(p=>p.active&&!p.price_pending).length,drafts=state.products.filter(p=>p.price_pending).length,low=state.products.filter(p=>p.active&&p.stock<=5).length;return `<section class="catalog-studio"><div class="admin-section-intro"><span>كتالوج ولعه</span><h2>المنتجات</h2><p>صورة المنتج، السعر، الكمية وحالة النشر في بطاقات واضحة.</p></div><div class="studio-stats"><article><span>المنتجات المنشورة</span><strong>${active}</strong><small>ظاهرة في تطبيق العميل</small></article><article><span>المسودات</span><strong>${drafts}</strong><small>تحتاج سعرًا أو مراجعة</small></article><article><span>مخزون منخفض</span><strong>${low}</strong><small>٥ قطع أو أقل</small></article></div><details class="card catalog-create"><summary>✚ إضافة منتج جديد <small>افتح نموذج البيانات والصورة</small></summary><div class="catalog-create-body"><label>اسم المنتج<input id="p-name" placeholder="مثال: أرز ١ كجم"></label><label>القسم<select id="p-category" onchange="renderProductMerchantChoices()">${options(state.categories.filter(c=>c.active).map(c=>c.name))}</select></label><label>مكان الاستلام<select id="p-merchant">${state.merchants.filter(m=>m.active).map(m=>`<option value="${m.id}" data-category="${esc(m.category)}">${esc(m.name)} · ${esc(m.area)}</option>`).join('')}</select></label><label>السعر بالجنيه<input id="p-price" type="number" min="0" step="0.01" placeholder="0.00"></label><label>الكمية المتاحة<input id="p-stock" type="number" min="0" placeholder="0"></label><label>صورة المنتج<input id="p-image" type="file" accept="image/png,image/jpeg,image/webp"></label><label class="catalog-check"><input id="p-rx" type="checkbox"> يحتاج وصفة طبية</label><button onclick="addProduct()">حفظ المنتج</button></div><details class="import-panel"><summary>استيراد أسماء منتجات كمسودات</summary><p>كل منتج في سطر؛ أضف السعر والكمية بعد الاستيراد.</p><label>السوبر ماركت<select id="import-merchant">${state.merchants.filter(m=>m.active&&m.category==='سوبر ماركت').map(m=>`<option value="${m.id}">${esc(m.name)}</option>`).join('')}</select></label><label>أسماء المنتجات<textarea id="import-names" placeholder="اسم المنتج — الحجم\nاسم المنتج التالي"></textarea></label><button onclick="importProductNames()">استيراد المسودات</button></details></details><section class="catalog-list-head"><div><h3>قائمة المنتجات</h3><p>ابحث، راجع الصورة والسعر ثم احفظ التعديلات من بطاقة المنتج.</p></div><label>بحث في الاسم أو القسم<input aria-label="بحث المنتجات" value="${esc(adminProductQuery)}" oninput="adminProductQuery=this.value;adminProductLimit=40;refreshAdminProductList()" placeholder="ابحث عن منتج…"></label></section><div class="card" id="admin-product-list">${adminProductRows()}</div></section>`}
function adminCommissionStudio(){const kinds=[{key:'products',label:'توصيل المنتجات',icon:'▣',hint:'منتجات السوبر ماركت والصيدلية'},{key:'delivery',label:'توصيل أوردر',icon:'↗',hint:'طلبات التوصيل المباشر'},{key:'custom',label:'خدمة أخرى',icon:'✦',hint:'الخدمات الخاصة'},...rideVehicles.map(v=>({key:v.key,label:v.label,icon:v.icon,hint:'المشاوير بهذه المركبة'}))];return `<section class="commission-studio"><div class="admin-section-intro"><span>إدارة العمولات</span><h2>نسب ولعه</h2><p>كل خدمة لها نسبتها الخاصة، وتثبت على الطلب وقت تسعيره.</p></div><div class="commission-note"><span>٪</span><p><strong>مثال سريع</strong><br>لو سعر التوصيل ٥٠ جنيه ونسبة ولعه ١٠٪: حصة ولعه ٥ جنيه، وصافي الطيار ٤٥ جنيه.</p></div><div class="commission-grid">${kinds.map(v=>`<article class="commission-tile"><div class="commission-tile-head"><span class="commission-icon">${v.icon}</span><div><strong>${esc(v.label)}</strong><small>${esc(v.hint)}</small></div></div><div class="commission-current"><span>النسبة الحالية</span><b>${esc(state.settings['commission_'+v.key]||'0')}٪</b></div><label>تعديل النسبة المئوية<input id="commission-rate-${v.key}" type="number" min="0" max="100" step="0.01" value="${esc(state.settings['commission_'+v.key]||'0')}" inputmode="decimal"></label><button onclick="saveCommissionRate('${v.key}')">حفظ نسبة ${esc(v.label)}</button></article>`).join('')}</div></section>`}

function adminCatalogCards(kind){const categories=kind==='categories',items=categories?state.categories:state.services,staff=Array.isArray(state.staff_permissions);return `<section class="catalog-studio"><div class="admin-section-intro"><span>تنظيم التطبيق</span><h2>${categories?'أقسام المنتجات':'الخدمات'}</h2><p>${categories?'صور واضحة وأقسام مرتبة لتسهيل اختيار العميل.':'خدمات ولعه وحالة ظهورها في تطبيق العميل.'}</p></div>${staff?'':`<div class="card"><label>${categories?'اسم القسم الجديد':'اسم الخدمة الجديدة'}<input id="${categories?'category-name':'service-name'}" placeholder="${categories?'مثال: مستلزمات المنزل':'مثال: توصيل مستندات'}"></label><button onclick="${categories?'createCategory':'createService'}()">إضافة ${categories?'قسم':'خدمة'}</button></div>`}<div class="catalog-studio-grid">${items.map(c=>{const products=categories?state.products.filter(p=>p.category===c.name):[],image=products.find(p=>p.image)?.image;return `<article class="catalog-studio-card"><div class="catalog-studio-art">${image?`<img loading="lazy" decoding="async" src="${esc(image)}" alt="${esc(c.name)}">`:`<svg viewBox="0 0 240 150" role="img" aria-label="${esc(c.name)}"><circle cx="120" cy="75" r="58" fill="#ffdfc0"/><path d="M75 57h90v57H75zM88 57V43h64v14M75 80h90M110 72h20v16h-20" fill="none" stroke="#ae4926" stroke-width="7" stroke-linejoin="round"/><path d="M56 119h128" stroke="#eab18d" stroke-width="5" stroke-linecap="round"/></svg>`}</div><div class="catalog-studio-body"><span class="tag">${c.active?'ظاهر للعملاء':'مخفي مؤقتًا'}</span><h3>${esc(c.name)}</h3><p>${categories?products.length+' منتج في القسم':'خدمة متاحة من تطبيق العميل'}</p>${staff?'':`<button class="${c.active?'secondary':''}" onclick="${categories?`toggleCategory(decodeURIComponent('${encodeURIComponent(c.name)}'),${!c.active})`:`toggleService('${c.key}',${!c.active})`}">${c.active?'إخفاء مؤقت':'إظهار للعملاء'}</button>`}</div></article>`}).join('')||'<div class="empty">لم تتم إضافة عناصر بعد.</div>'}</div></section>`}

function googleMapsSettingsPanel(){return `<section class="card"><div class="admin-section-intro"><span>الخرائط والملاحة</span><h2>ربط خرائط Google</h2><p>خريطة جوجل داخل التطبيق، مع فتح الملاحة على الموبايل.</p></div><p id="google-map-status" role="status">${state.settings.google_maps_browser_key?'مفتاح جوجل محفوظ · اختبر الخريطة للتأكد من التفعيل.':'أضف مفتاح جوجل لتفعيل الخريطة الداخلية.'}</p><label>مفتاح Maps JavaScript API<input id="google-map-key" type="password" autocomplete="off" placeholder="الصق المفتاح هنا" spellcheck="false" dir="ltr"></label><p class="muted">في حساب Google Cloud: فعّل Maps JavaScript API والفوترة، واجعل المفتاح مسموحًا فقط لموقع https://walla3ha.com/* ولخدمة Maps JavaScript API.</p><button onclick="saveGoogleMapsConnection()">حفظ وربط الخريطة</button><button class="secondary" onclick="openAdminPage('admin-map-section')">فتح الخريطة للاختبار</button></section>`}
async function saveGoogleMapsConnection(){const input=$('google-map-key'),statusEl=$('google-map-status'),key=input.value.trim();if(!/^AIza[A-Za-z0-9_-]{35}$/.test(key)){statusEl.textContent='أدخل مفتاح Maps JavaScript API الصحيح من جوجل.';return}statusEl.textContent='جارٍ حفظ الربط…';try{await featureAPI('maps-settings',{browser_key:key});googleMapsReadyPromise=null;input.value='';await refresh(true);$('google-map-status').textContent='تم حفظ المفتاح. افتح الخريطة للاختبار؛ يلزم تفعيل الفوترة والخدمة في حساب جوجل.'}catch(e){if(statusEl.isConnected)statusEl.textContent=e.message}}
